from typing import List

class Solution:
    def maximumAmount(self, coins: List[List[int]]) -> int:
        m, n = len(coins), len(coins[0])
        NEG_INF = -10**18
        # dp[i][j][k] : max coins reaching (i,j) having used k neutralizations
        dp = [[[NEG_INF]*3 for _ in range(n)] for __ in range(m)]

        # starting cell
        val = coins[0][0]
        dp[0][0][0] = val
        if val < 0:
            # we can neutralize the starting robber
            dp[0][0][1] = 0

        # first row
        for j in range(1, n):
            for k in range(3):
                if dp[0][j-1][k] == NEG_INF:
                    continue
                cur = coins[0][j]
                # without neutralizing this cell
                dp[0][j][k] = max(dp[0][j][k], dp[0][j-1][k] + cur)
                # neutralize if possible
                if k < 2 and cur < 0:
                    dp[0][j][k+1] = max(dp[0][j][k+1], dp[0][j-1][k])

        # first column
        for i in range(1, m):
            for k in range(3):
                if dp[i-1][0][k] == NEG_INF:
                    continue
                cur = coins[i][0]
                dp[i][0][k] = max(dp[i][0][k], dp[i-1][0][k] + cur)
                if k < 2 and cur < 0:
                    dp[i][0][k+1] = max(dp[i][0][k+1], dp[i-1][0][k])

        # rest of the grid
        for i in range(1, m):
            for j in range(1, n):
                cur = coins[i][j]
                for k in range(3):
                    # from top
                    if dp[i-1][j][k] != NEG_INF:
                        dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k] + cur)
                        if k < 2 and cur < 0:
                            dp[i][j][k+1] = max(dp[i][j][k+1], dp[i-1][j][k])
                    # from left
                    if dp[i][j-1][k] != NEG_INF:
                        dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k] + cur)
                        if k < 2 and cur < 0:
                            dp[i][j][k+1] = max(dp[i][j][k+1], dp[i][j-1][k])

        return max(dp[m-1][n-1])  # maximum over used neutralizations
