from collections import deque

class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # Extract unique weights and sort them
        weights = sorted({w for _,_,w in edges})
        if not weights:
            return -1

        # Build adjacency lists once, sorted by weight for efficient filtering
        adj = [[] for _ in range(n)]          # forward edges (u -> v)
        rev_adj = [[] for _ in range(n)]      # reverse edges (v -> u)
        for a,b,w in edges:
            adj[a].append((b,w))
            rev_adj[b].append((a,w))

        # Helper to test a given weight limit
        def feasible(limit: int) -> bool:
            # Reverse BFS from 0 using edges with weight <= limit
            q = deque([0])
            reachable = [False]*n
            reachable[0] = True
            while q:
                v = q.popleft()
                for u,w in rev_adj[v]:
                    if w <= limit and not reachable[u]:
                        reachable[u] = True
                        q.append(u)
            if not all(reachable):
                return False

            # For each node except 0, ensure at least one outgoing edge to a reachable node
            for u in range(1, n):
                ok = False
                for v,w in adj[u]:
                    if w <= limit and reachable[v]:
                        ok = True
                        break
                if not ok:
                    return False
            return True

        # Binary search over sorted weights
        lo, hi = 0, len(weights)-1
        ans = -1
        while lo <= hi:
            mid = (lo+hi)//2
            if feasible(weights[mid]):
                ans = weights[mid]
                hi = mid-1
            else:
                lo = mid+1
        return ans
