def solve() -> None:
    it = iter(sys.stdin.read().strip().split())
    N = int(next(it))
    A = [0] + [int(next(it)) for _ in range(N)]  # 1-indexed
    Q = int(next(it))

    INF = N + 2

    # compute next[i]: smallest j>i with A[i]*2 <= A[j]
    nxt = [INF] * (N + 1)
    j = 1
    for i in range(1, N + 1):
        if j <= i:
            j = i + 1
        while j <= N and A[i] * 2 > A[j]:
            j += 1
        if j <= N:
            nxt[i] = j
        else:
            nxt[i] = INF

    # jump table: after pairing at pos, next start is nxt[pos]+1
    LOG = (N+2).bit_length()
    jump = [[INF] * (N + 3) for _ in range(LOG)]
    for i in range(1, N + 1):
        if nxt[i] <= N:
            jump[0][i] = nxt[i] + 1
        else:
            jump[0][i] = INF

    for k in range(1, LOG):
        prev = jump[k-1]
        cur = jump[k]
        for i in range(1, N + 1):
            nxtpos = prev[i]
            cur[i] = prev[nxtpos] if nxtpos <= N else INF

    out_lines = []
    for _ in range(Q):
        L = int(next(it))
        R = int(next(it))
        pos = L
        pairs = 0
        for k in range(LOG-1, -1, -1):
            nxtpos = jump[k][pos]
            if nxtpos <= R:
                pairs += 1 << k
                pos = nxtpos
        out_lines.append(str(pairs))
    sys.stdout.write("\n".join(out_lines))

