from typing import List

class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        m = n // 2                     # number of pairs
        INF = 10**18

        # dp[cl][cr] for current pair i
        prev = [[INF]*3 for _ in range(3)]

        # initialize for pair 0
        i = 0
        for cl in range(3):
            for cr in range(3):
                if cl == cr:          # pair constraint
                    continue
                prev[cl][cr] = cost[i][cl] + cost[n-1-i][cr]

        # iterate over remaining pairs
        for i in range(1, m):
            cur = [[INF]*3 for _ in range(3)]
            for cl in range(3):
                for cr in range(3):
                    if cl == cr:
                        continue
                    add = cost[i][cl] + cost[n-1-i][cr]
                    best = INF
                    for pl in range(3):
                        if pl == cl:   # adjacent left constraint
                            continue
                        for pr in range(3):
                            if pr == cr:   # adjacent right constraint
                                continue
                            val = prev[pl][pr] + add
                            if val < best:
                                best = val
                    cur[cl][cr] = best
            prev = cur

        # answer is min over last pair states
        ans = INF
        for cl in range(3):
            for cr in range(3):
                if prev[cl][cr] < ans:
                    ans = prev[cl][cr]
        return ans
