# Solution for counting connected bipartite graphs with equal parity distances from vertex 1

import sys
from math import comb

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    N, P = map(int, data)
    a = b = N // 2

    # Precompute binomial coefficients modulo P up to 900
    max_n = a * b
    fact = [1] * (max_n + 1)
    inv_fact = [1] * (max_n + 1)

    for i in range(1, max_n + 1):
        fact[i] = fact[i - 1] * i % P

    # Fermat inverse since P is prime
    inv_fact[max_n] = pow(fact[max_n], P - 2, P)
    for i in range(max_n, 0, -1):
        inv_fact[i - 1] = inv_fact[i] * i % P

    def nCk(n, k):
        if k < 0 or k > n:
            return 0
        return fact[n] * inv_fact[k] % P * inv_fact[n - k] % P

    # Precompute binomials for selecting vertices
    binomA = [[0] * (a + 1) for _ in range(a)]
    binomB = [[0] * (b + 1) for _ in range(b)]
    for i in range(a):
        for j in range(i + 1):
            binomA[i][j] = nCk(i, j)
    for i in range(b):
        for j in range(i + 1):
            binomB[i][j] = nCk(i, j)

    # DP tables: Tpoly[a1][b1] = list of counts for edges 0..a1*b1
    Tpoly = [[[] for _ in range(b + 1)] for __ in range(a + 1)]
    Cpoly = [[[] for _ in range(b + 1)] for __ in range(a + 1)]

    # Fill Tpoly
    for a1 in range(0, a + 1):
        for b1 in range(0, b + 1):
            max_edges = a1 * b1
            arr = [0] * (max_edges + 1)
            for m in range(max_edges + 1):
                arr[m] = nCk(max_edges, m)
            Tpoly[a1][b1] = arr

    # Compute Cpoly via recurrence
    for a1 in range(0, a + 1):
        for b1 in range(0, b + 1):
            if a1 == 0 and b1 == 0:
                continue
            max_edges = a1 * b1
            # Start with total graphs
            C_arr = Tpoly[a1][b1][:]  # copy

            if a1 == 0 or b1 == 0:
                # Only possible component is single vertex if a1==1,b1==0 or a1==0,b1==1
                # For other cases, connectedness impossible; C_arr already zero except maybe m=0 for single vertex
                # No subtraction needed
                pass
            else:
                # Subtract contributions where component containing vertex1 is smaller
                for sub_a in range(1, a1 + 1):
                    for sub_b in range(0, b1 + 1):
                        if sub_a == a1 and sub_b == b1:
                            continue
                        # choose vertices for this component containing vertex1
                        waysA = binomA[a1 - 1][sub_a - 1]
                        waysB = binomB[b1][sub_b]
                        if waysA == 0 or waysB == 0:
                            continue
                        coeff = waysA * waysB % P

                        # convolution of Cpoly[sub_a][sub_b] and Tpoly[a1-sub_a][b1-sub_b]
                        poly1 = Cpoly[sub_a][sub_b]
                        poly2 = Tpoly[a1 - sub_a][b1 - sub_b]
                        # convolution
                        conv_len = len(poly1) + len(poly2) - 1
                        conv = [0] * conv_len
                        for i, v1 in enumerate(poly1):
                            if v1 == 0:
                                continue
                            for j, v2 in enumerate(poly2):
                                if v2 == 0:
                                    continue
                                conv[i + j] = (conv[i + j] + v1 * v2) % P
                        # subtract coeff * conv from C_arr
                        for idx in range(min(len(C_arr), len(conv))):
                            C_arr[idx] = (C_arr[idx] - coeff * conv[idx]) % P
            # Ensure non-negative modulo
            Cpoly[a1][b1] = [x % P for x in C_arr]

    # Output answers for M from N-1 to N*(N-1)//2
    max_M = N * (N - 1) // 2
    res = []
    for M in range(N - 1, max_M + 1):
        if M <= a * b:
            res.append(str(Cpoly[a][b][M] % P))
        else:
            res.append('0')
    print(' '.join(res))

if __name__ == "__main__":
    solve()
