from typing import List

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Parse timestamps and sort events.
        parsed_events = []
        for e in events:
            typ, ts_str, arg = e
            ts = int(ts_str)
            parsed_events.append((ts, 0 if typ == "OFFLINE" else 1, typ, arg))
        parsed_events.sort()  # OFFLINE before MESSAGE at same timestamp

        mentions = [0] * numberOfUsers
        offline_until = {}  # user_id -> time when they come online

        for ts, _, typ, arg in parsed_events:
            # Bring back users whose offline period ended
            to_remove = [u for u, end in offline_until.items() if end <= ts]
            for u in to_remove:
                del offline_until[u]

            if typ == "OFFLINE":
                uid = int(arg)
                # guaranteed to be online at this moment
                offline_until[uid] = ts + 60
            else:  # MESSAGE
                tokens = arg.split()
                if "ALL" in tokens:
                    for u in range(numberOfUsers):
                        mentions[u] += 1
                elif "HERE" in tokens:
                    for u in range(numberOfUsers):
                        if u not in offline_until:  # online
                            mentions[u] += 1
                else:
                    for tok in tokens:
                        if tok.startswith("id"):
                            uid = int(tok[2:])
                            mentions[uid] += 1

        return mentions
