        n = len(s)
        ans = 0
        for i in range(n):
            d = int(s[i])
            if d == 0:
                continue
            rem = 0          # remainder of current substring modulo d
            pow10 = 1        # 10^k mod d for the current position k
            # We only need to look back at most 200 characters (proof in editorial)
            for j in range(i, max(-1, i - 200), -1):
