        n = len(grid)
        # Collect diagonals
        diag_map = {}
        for i in range(n):
            for j in range(n):
                d = i - j
                diag_map.setdefault(d, []).append((i, j))
        # Process each diagonal
        for d, cells in diag_map.items():
