from typing import List, Dict

class Solution:
    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        # Map each element value to the smallest index where it appears
        val_to_index: Dict[int, int] = {}
        for idx, val in enumerate(elements):
            if val not in val_to_index:
                val_to_index[val] = idx

        result: List[int] = []

        for g in groups:
            best_idx = -1
            # iterate over all divisors of g
            d = 1
            while d * d <= g:
                if g % d == 0:
                    # divisor d
                    if d in val_to_index:
                        idx = val_to_index[d]
                        if best_idx == -1 or idx < best_idx:
                            best_idx = idx
                    # paired divisor g//d
                    other = g // d
                    if other != d and other in val_to_index:
                        idx = val_to_index[other]
                        if best_idx == -1 or idx < best_idx:
                            best_idx = idx
                d += 1
            result.append(best_idx)

        return result
