import sys

MOD = 998244353

def prime_factors(n):
    d = {}
    p = 2
    while p * p <= n:
        while n % p == 0:
            d[p] = d.get(p, 0) + 1
            n //= p
        p += 1 if p == 2 else 2
    if n > 1:
        d[n] = d.get(n, 0) + 1
    return d

def solve():
    it = iter(sys.stdin.read().strip().split())
    N = int(next(it))
    A = [int(next(it)) for _ in range(N-1)]

    # For each prime, collect exponents a_i
    primes = {}
    for val in A:
        facs = prime_factors(val)
        for p, e in facs.items():
            primes.setdefault(p, []).append(e)

    ans = 1
    for p, exps in primes.items():
        # For indices where exponent is zero, we treat as 0
        a_list = []
        for val in A:
            facs = prime_factors(val)
            a_list.append(facs.get(p, 0))
        max_h = sum(a_list)  # maximum possible height
        dp = [0] * (max_h + 1)
        dp[0] = 1
        for a in a_list:
            ndp = [0] * (max_h + 1)
            if a == 0:
                # only stay
                for h in range(max_h + 1):
                    if dp[h]:
                        ndp[h] = (ndp[h] + dp[h] * pow(p, h, MOD)) % MOD
            else:
                for h in range(max_h + 1):
                    val = dp[h]
                    if not val:
                        continue
                    # s = +1 : h' = h - a
                    if h >= a:
                        h2 = h - a
                        ndp[h2] = (ndp[h2] + val * pow(p, h2, MOD)) % MOD
                    # s = -1 : h' = h + a
                    if h + a <= max_h:
                        h2 = h + a
                        ndp[h2] = (ndp[h2] + val * pow(p, h2, MOD)) % MOD
            dp = ndp
        prime_sum = sum(dp) % MOD
        ans = (ans * prime_sum) % MOD

    # For primes not appearing in any A_i, they don't affect the product
    print(ans)

if __name__ == "__main__":
    solve()
