class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        if k > n or k == 0:
            return False

        for i in range(n - k + 1):
            # Check if all characters in s[i:i+k] are the same
            ch = s[i]
            if any(c != ch for c in s[i:i + k]):
                continue

            # Check left neighbor if it exists
            if i > 0 and s[i - 1] == ch:
                continue

            # Check right neighbor if it exists
            if i + k < n and s[i + k] == ch:
                continue

            return True
