class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n, m = len(grid), len(grid[0])
        # Directions in clockwise order: TL-BR, TR-BL, BR-TL, BL-TR
        dirs = [(1, 1), (1, -1), (-1, -1), (-1, 1)]
        # Pattern: 0->1, 1->2, 2->0, 3->2
        pat = [1, 2, 0, 2]

        # dp[dir][t][i][j] : length of straight segment starting at (i,j)
        # with current cell having pattern offset t, moving in direction dir
        dp = [[[ [0]*m for _ in range(n) ] for __ in range(4)] for ___ in range(4)]

        # Precompute dp for each direction
        for d, (dr, dc) in enumerate(dirs):
            # iterate cells in reverse order along this direction
            for i in range(n-1, -1, -1):
                for j in range(m-1, -1, -1):
                    ni, nj = i + dr, j + dc
                    for t in range(4):
                        if grid[i][j] != pat[t]:
                            dp[d][t][i][j] = 0
                        else:
                            if 0 <= ni < n and 0 <= nj < m and grid[ni][nj] == pat[(t+1)%4]:
                                dp[d][t][i][j] = 1 + dp[d][(t+1)%4][ni][nj]
                            else:
                                dp[d][t][i][j] = 1

        best = 0
        # For each start cell with value 1 (t=0)
        for i in range(n):
            for j in range(m):
                if grid[i][j] != 1:
                    continue
                # try each initial direction
                for d, (dr, dc) in enumerate(dirs):
                    steps = 0
                    ci, cj = i, j
                    t = 0  # current offset
                    while True:
                        steps += 1
                        # pivot at (ci,cj)
                        # next direction is clockwise: (d+1)%4
                        nd = (d + 1) % 4
                        ni, nj = ci + dirs[nd][0], cj + dirs[nd][1]
                        if 0 <= ni < n and 0 <= nj < m:
                            # offset for next cell is (t+1)%4
                            nxt_len = dp[nd][(t+1)%4][ni][nj]
                            best = max(best, steps + nxt_len)
                        # move to next cell in current direction
                        ci += dr
                        cj += dc
                        t = (t + 1) % 4
                        if not (0 <= ci < n and 0 <= cj < m):
                            break
                        if grid[ci][cj] != pat[t]:
                            break

        return best
