class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        n = len(points)

        # Precompute all pairwise Manhattan distances
        dist_matrix = [[0]*n for _ in range(n)]
        for i in range(n):
            xi, yi = points[i]
            for j in range(i+1, n):
                xj, yj = points[j]
                d = abs(xi - xj) + abs(yi - yj)
                dist_matrix[i][j] = d
                dist_matrix[j][i] = d

        # Check if we can pick k points with min distance >= d
        def can(d: int) -> bool:
            # list of candidate indices
            candidates = list(range(n))

            def dfs(selected: int, idx_list: List[int]) -> bool:
                if selected == k:
                    return True
                # pruning: not enough remaining points
                if len(idx_list) + selected < k:
                    return False

                # choose next point
                for i, p in enumerate(idx_list):
                    # try to add point p
                    new_candidates = []
                    for q in idx_list[i+1:]:
                        if dist_matrix[p][q] >= d:
                            new_candidates.append(q)
                    if dfs(selected + 1, new_candidates):
                        return True
                return False

            return dfs(0, candidates)

        # Binary search on distance
        lo, hi = 0, 2*side  # maximum possible Manhattan distance on the square
        best = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if can(mid):
                best = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return best
