    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        word = [None] * L

        # Apply all 'T' constraints
        for i, ch in enumerate(str1):
            if ch == 'T':
                for j in range(m):
                    pos = i + j
                    if word[pos] is None:
                        word[pos] = str2[j]
                    elif word[pos] != str2[j]:
                        return ""  # conflict

        # Prepare F windows
        f_windows = []          # list of dicts: {'matched': int, 'unknown': int}
        pos_to_windows = [[] for _ in range(L)]  # list of (win_idx, offset)
        for i, ch in enumerate(str1):
            if ch == 'F':
                matched = 0
                unknown = 0
                for j in range(m):
                    pos = i + j
                    if word[pos] is None:
                        unknown += 1
                    elif word[pos] == str2[j]:
                        matched += 1
                if matched == m:
                    return ""  # already equal to str2
                win_idx = len(f_windows)
                f_windows.append({'matched': matched, 'unknown': unknown})
                for j in range(m):
                    pos = i + j
                    pos_to_windows[pos].append((win_idx, j))

        # Greedy fill remaining positions
        for pos in range(L):
            if word[pos] is not None:
                continue
            # try letters from 'a' to 'z'
            for c in map(chr, range(ord('a'), ord('z') + 1)):
                bad = False
                for win_idx, offset in pos_to_windows[pos]:
                    win = f_windows[win_idx]
                    if c == str2[offset]:
                        # would increase matched
                        if win['matched'] + 1 == m:
                            bad = True
                            break
                if not bad:
                    word[pos] = c
                    # update windows
                    for win_idx, offset in pos_to_windows[pos]:
                        win = f_windows[win_idx]
                        if c == str2[offset]:
                            win['matched'] += 1
                        else:
                            # unknown decreases implicitly by not matching; no need to track
                            pass
                    break
            else:
                # should never happen, but just in case
                return ""

        return "".join(word)
