class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # dp[i][j] will be a dict: length -> minimal cost to achieve that length
        dp = [[dict() for _ in range(n)] for _ in range(n)]

        # Helper to compute minimal steps to make two chars equal
        def cost_to_match(a: str, b: str) -> int:
            diff = abs(ord(a) - ord(b))
            return min(diff, 26 - diff)

        # Base cases
        for i in range(n):
            dp[i][i] = {1: 0}          # single char palindrome
        for i in range(n - 1):
            dp[i][i + 1] = {0: 0}      # empty palindrome
            c = cost_to_match(s[i], s[i + 1])
            if c <= k:
                dp[i][i + 1][2] = c

        # Fill DP for substrings of length >=3
        for length in range(3, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                cur = dict()

                # Option 1: skip left character
                for l, c in dp[i + 1][j].items():
                    if l not in cur or c < cur[l]:
                        cur[l] = c

                # Option 2: skip right character
                for l, c in dp[i][j - 1].items():
                    if l not in cur or c < cur[l]:
                        cur[l] = c

                # Option 3: match both ends
                add_cost = cost_to_match(s[i], s[j])
                if add_cost <= k:
                    inner = dp[i + 1][j - 1]
                    for l, c in inner.items():
                        new_len = l + 2
                        new_cost = c + add_cost
                        if new_cost <= k:
                            if new_len not in cur or new_cost < cur[new_len]:
                                cur[new_len] = new_cost

                dp[i][j] = cur

        # Find the maximum length with cost <= k
        best_len = 0
        for l, c in dp[0][n - 1].items():
            if c <= k and l > best_len:
                best_len = l
        return best_len
