from typing import List

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        # Build segment tree over baskets capacities
        size = 1
        while size < n:
            size <<= 1
        seg = [-10**18] * (2*size)
        for i, cap in enumerate(baskets):
            seg[size + i] = cap
        for i in range(size-1, 0, -1):
            seg[i] = max(seg[2*i], seg[2*i+1])

        def update(pos: int, val: int):
            """Set basket at pos to val (used -> -inf)."""
            i = size + pos
            seg[i] = val
            i >>= 1
            while i:
                seg[i] = max(seg[2*i], seg[2*i+1])
                i >>= 1

        def find_first(val: int) -> int:
            """Return leftmost index with capacity >= val, or -1 if none."""
            if seg[1] < val:
                return -1
            idx = 1
            l, r = 0, size-1
            while idx < size:
                mid = (l + r) // 2
                if seg[2*idx] >= val:
                    idx = 2*idx
                    r = mid
                else:
                    idx = 2*idx + 1
                    l = mid + 1
            return l if l < n else -1

        unplaced = 0
        for f in fruits:
            pos = find_first(f)
            if pos == -1:
                unplaced += 1
            else:
                update(pos, -10**18)   # mark as used

        return unplaced
