class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        from functools import lru_cache

        def count_upto(n: int, S: int) -> int:
            digits = list(map(int, str(n)))
            L = len(digits)

            @lru_cache(None)
            def dfs(pos: int, tight: bool, started: bool,
                    sum_so_far: int, prod_mod: int) -> int:
                if pos == L:
                    return int(started and sum_so_far == S and prod_mod % S == 0)
                limit = digits[pos] if tight else 9
                total = 0
                for d in range(0, limit + 1):
                    ntight = tight and (d == limit)
                    nstarted = started or d != 0
                    nsum = sum_so_far + d if nstarted else sum_so_far
                    # product: if not started yet, keep prod_mod as 1 (neutral)
                    nprod = prod_mod
                    if nstarted:
                        # when starting with first non-zero digit, previous prod was 1
                        if not started:
                            nprod = d % S
                        else:
                            nprod = (prod_mod * d) % S
                    total += dfs(pos + 1, ntight, nstarted, nsum, nprod)
                return total

            return dfs(0, True, False, 0, 1)

        def count_range(a: int, b: int) -> int:
            total = 0
            for S in range(1, 82):   # maximum possible digit sum for up to 9 digits
                total += count_upto(b, S) - count_upto(a - 1, S)
            return total

        return count_range(l, r)
