    if fixed_sums:
        S = next(iter(fixed_sums))

    # If S is not fixed, we can choose any large enough value.
    if S is None:
        # Just need to ensure that we can pick a non‑negative S
        # such that all required values are non‑negative.
        # Choosing S = max(A_known, B_known) works.
        max_val = 0
        for a in A:
            if a != -1:
                max_val = max(max_val, a)
        for b in B:
            if b != -1:
                max_val = max(max_val, b)
        S = max_val
    # Now check all constraints with this S
    for a, b in zip(A, B):
        if a == -1 and b == -1:
            continue
        if a != -1 and b != -1:
            # already checked sums equal
            continue
        if a == -1:
            # need to set A = S - b >= 0
            if S - b < 0:
                print("No")
                return
        else:  # b == -1
            if S - a < 0:
                print("No")
                return

    print("Yes")

if __name__ == "__main__":
    solve()
