class Solution:
    def longestPalindrome(self, s: str, t: str) -> int:
        # helper to generate all substrings including the empty string
        def substrings(st: str):
            n = len(st)
            res = [""]
            for i in range(n):
                for j in range(i + 1, n + 1):
                    res.append(st[i:j])
            return res

        subs_s = substrings(s)
        subs_t = substrings(t)

        def is_pal(x: str) -> bool:
            return x == x[::-1]

        max_len = 0
        for a in subs_s:
            for b in subs_t:
                cand = a + b
                if is_pal(cand):
                    max_len = max(max_len, len(cand))
        return max_len
