            continue
        if s_char in mapping:
            if mapping[s_char] != t_char:
                print(-1)
                return
        else:
            mapping[s_char] = t_char

    # Build graph for cycle detection
    visited = {}
    cycles = 0
    for src in mapping:
        if src in visited:
            continue
        stack = []
        cur = src
        while True:
            if cur in visited:
                # If we revisit a node in current stack, cycle found
                if cur in stack:
                    cycles += 1
                break
            visited[cur] = True
            stack.append(cur)
            nxt = mapping.get(cur)
            if not nxt:
                break
            cur = nxt

    ops = len(mapping) + cycles

    # Check if we have a free letter for cycle resolution
    if cycles > 0:
        used_letters = set(S)
        # After all operations, letters may change; but we just need a letter not in used_letters
        if len(used_letters) == 26:
            print(-1)
            return

    print(ops)

