from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # maximum possible absolute alternating sum
        max_sum = 12 * len(nums)
        offset = max_sum + 5          # small buffer
        size = 2 * offset + 1

        NEG_INF = -10**9
        # dp[parity][sum_offset] = max product achievable with that parity and sum
        dp = [[NEG_INF] * size for _ in range(2)]
        dp[0][offset] = 1   # empty subsequence

        best = -1
        for num in nums:
            newdp = [row[:] for row in dp]   # copy to allow skip
            for parity in (0, 1):
                row = dp[parity]
                for s_idx, prod in enumerate(row):
                    if prod == NEG_INF:
                        continue
                    # take this number
                    new_parity = 1 - parity
                    if parity == 0:
                        new_sum = s_idx + num
                    else:
                        new_sum = s_idx - num
                    if 0 <= new_sum < size:
                        new_prod = prod * num
                        if new_prod <= limit and new_prod > newdp[new_parity][new_sum]:
                            newdp[new_parity][new_sum] = new_prod
                            if new_sum == offset + k:
                                best = max(best, new_prod)
            dp = newdp

        return best
